/* ap_driver.r -- the resource fork of the COMBINED, Apple-shaped AirPort driver (k204).
 *
 * ONE shlb file, three PEF fragments in the data fork (OTModl$AirPortBCM + OTPortCfg$AirPortCfgHelper
 * + OTKrnl$AirPortScanner), declared by the 3-member 'cfrg' below (generated by make-airport-driver.py,
 * with the 'otan'/"OTKrnl$pScnr" scanner extension OT keys on). No INIT, no separate Startup vehicle:
 * OT scans this cfrg at boot, calls the scanner's OTScanPorts, and installs the driver itself. This is
 * the shape of Apple's `Apple Enet DLPI Support`, verified fragment-for-fragment.
 *
 * ⚠ STANDING (user): both version strings carry the build so Get Info shows the installed build. */
#include "Types.r"
#include "ap_driver_cfrg.r"    /* generated: the 3-member cfrg. Rez include is invisible to CMake --
                                * listed in the DEPENDS of the Rez command in CMakeLists. */

resource 'vers' (1, locked) {
    0x01, 0x99, beta, 219, verUS,
    "1.0b219",
    "AirPort Extreme 1.0b219 (k219 -- CLEARER NAME, AND WORKS ON MORE MACS. The network port now appears as "
    "AirPort Extreme in the TCP/IP control panel's Connect via menu, so it is clear which driver is in use. The "
    "driver also lets the card choose its antenna automatically instead of a setting fixed for the Power Mac G4 "
    "MDD, so Macs that wire the card's antennas differently can still receive, and it confirms the card is a "
    "Broadcom BCM4306 before using it. Restart normally.) "
    "(k217 was: OPEN NETWORKS. The driver now joins open (unencrypted) networks as well "
    "as WPA2 Personal: no password is asked, the four-way handshake is skipped, and data is sent in the clear. "
    "Choose an open network from the panel or the Control Strip the same way you choose a secured one. Restart "
    "normally.) "
    "(k216 was: THE NETWORK LIST STAYS STEADY. The list of nearby networks no longer "
    "rebuilds from scratch each time it looks; a network briefly missed in one scan stays on the list instead "
    "of flickering away, and only drops after it has been gone a while -- the way Apple's AirPort did it. Pair "
    "with the AirPort Extreme Strip 1.9 to choose a network straight from the Control Strip. Restart normally.) "
    "(k215 was: KEEP NETWORK ACCESS AFTER SWITCHING NETWORKS. When you switched to a "
    "different network, the Mac kept the first network's Internet settings and so lost access on the second; "
    "it now tells the system the network changed, so it gets fresh settings for the one you switched to. "
    "Restart normally.) "
    "(k214 was: JOIN A SECOND NETWORK WITHOUT REBOOTING. A bug let the Mac join only "
    "ONE network per startup: switching to a different network afterward always said the password was wrong, "
    "even when it was right, because the driver kept using the FIRST network's key. Now each network's own "
    "password is used, so you can switch networks freely. Restart normally.) "
    "(k213 was: TELLS YOU WHEN A PASSWORD IS WRONG. If the password you type for a "
    "network is incorrect, the Mac now says so and asks you to enter it again, instead of trying forever with "
    "\"Looking for ...\". A wrong Wi-Fi password can only be detected while connecting (the base station is the "
    "only thing that can check it), so an incorrect one is never kept -- it is removed the moment the base "
    "station rejects it. You can also forget a saved network from the control panel. Restart normally.) "
    "(k212 was: JOINS THE NETWORK YOU PICKED, AND SHOWS EACH NETWORK ONCE. When you "
    "choose a network in the control panel, the Mac now joins THAT network, even if it was briefly out of the "
    "last scan -- it no longer substitutes another saved network that happens to be in range. And a base "
    "station that broadcasts several networks from one radio is now listed once per name, as Apple's software "
    "did. Restart normally.) "
    "(k211 was: SAYS \"NO NETWORK SELECTED\" INSTEAD OF SEARCHING FOREVER. Before you "
    "have chosen a network, the driver now reports that it is idle, so the control panel and Control Strip say "
    "\"No AirPort network is selected\" with no spinner, instead of \"Looking for AirPort networks\" that never "
    "stopped. Choosing a network and connecting are unchanged. Restart normally.) "
    "(k210 was: CHOOSE A NETWORK, NO PASSWORD BUILT IN. The driver no longer has a "
    "network or password compiled into it: you choose a network and type its password in the AirPort Extreme "
    "control panel, which stores it and tells the driver, and from then on the Mac joins it on its own. WPA2 "
    "Personal networks; open networks are coming. ⚠ On the first start after installing this, the Mac will "
    "not connect until you choose your network in the control panel once. Restart normally.) "
    "(k209 was: FINDS ITS NETWORK ON ANY CHANNEL, AND LISTS THE NETWORKS AROUND IT. "
    "The driver is no longer fixed to one Wi-Fi channel: if its network is not where it expects, it listens "
    "across every channel to find it. It also builds a list of the Wi-Fi networks in range. Restart normally.) "
    "(k208 was: GROUP KEY RENEWALS ANSWERED. A WPA2 base station changes the key "
    "its broadcast traffic is sent under on a timer (hourly on many) and waits for every computer to "
    "confirm. The driver now confirms, so the base station no longer disconnects the Mac a few seconds "
    "after each change. Restart normally.) "
    "(k207 was: AIRPORT OFF AND ON. The control panel's Turn AirPort Off button "
    "and the Control Strip module's menu now work: off says goodbye to the base station and turns "
    "the radio off; on turns it back on and rejoins. Restart normally.) "
    "(k206 was: ITS OWN ICON. The extension now shows the AirPort Extreme icon, "
    "so it is told apart from Apple's AirPort extensions at a glance.) "
    "(k205 was: STATUS FOR THE CONTROL PANEL AND CONTROL STRIP. The driver now "
    "publishes what it is doing -- connected or not, the network, the base station, the channel, the "
    "signal strength in the AirPort app's five levels, and this card's AirPort ID -- in a small block "
    "that the new AirPort Extreme control panel and Control Strip module read. No change to how it "
    "connects. Restart normally.) "
    "(k204 was: RECONNECTS BY ITSELF. Until now the driver joined the network once, "
    "at startup: if that failed, or if the connection dropped later (the base station restarting, or "
    "sending the Mac away), it stayed offline until a restart. It now watches the link -- the base "
    "station's beacons, and any message telling it to leave -- and joins again on its own, holding "
    "outgoing data meanwhile so nothing is lost. It tries whenever the base station can be heard, and "
    "backs off while it cannot. It also records when the base station changes its group key (not answered "
    "yet) and writes its log to disk every half minute, so a crash leaves a record. Restart normally.) "
    "(k203 was: A STEADIER JOIN AND FASTER RETRIES. k202 reached 1519 KB/s up and "
    "1995 down, but one boot failed to connect: the access point asked for a handshake step again and "
    "the driver gave up instead of answering, with no second try. Now it answers the repeat (as the "
    "standard requires and Linux does), checks its reply was received, and tries the join up to 3 times. "
    "Also: a packet that has to be resent now goes out at the next lower speed instead of the slowest "
    "one (1 Mbps), which was wasting about 15% of upload time. COLD boot.) "
    "(k202 was: NO MORE DROPPED SENDS. k201 downloaded at 1804 KB/s, faster than "
    "Tiger, but uploads kept stalling: when the card's send queue was full, the driver threw the "
    "packet away, and the Mac's networking needed up to 0.7 s to notice and resend. Now a packet "
    "that does not fit waits in line and goes out as soon as there is room, and the networking stack "
    "is told to slow down meanwhile -- what Linux does. Also: the driver now properly unhooks its "
    "interrupt handler when it is unloaded. COLD boot.) "
    "(k201 was: DON'T READ A FRAME THE CARD IS STILL WRITING. k200's faster "
    "receive worked (each frame 30x cheaper, upload up to 1431 KB/s) but downloads collapsed to 135 "
    "KB/s: the receiver now reached a buffer while the card was still filling it, took the half-written "
    "frame, dropped it, and marked the buffer used -- 13% of download packets had to be resent. Now it "
    "never touches the buffer the card is currently writing, exactly as Linux's b43 driver does, and "
    "counts how often it waited. COLD boot.) "
    "(k200 was: FASTER RECEIVE. k199's fast encryption took NetBench from "
    "356/329 KB/s to 1331/1152, and its new timing showed the next limit: every received frame cost "
    "~565 microseconds just to copy out of the card's buffer -- the whole 2400-byte buffer, a byte at a "
    "time -- so bursts backed up, acknowledgements came late, and downloads spent 45% of their time "
    "waiting. Now only the frame is copied, a word at a time, and transmit encrypts into ordinary "
    "memory before one quick copy into the card's buffer. A startup probe measures how slow the card's "
    "buffer memory really is. COLD boot.) "
    "(k199 was: FAST ENCRYPTION. With Bluetooth unplugged, k198 moved 356 KB/s "
    "up and 329 down against Tiger's 2085/1685 on the same card, and the radio was not the limit (54 "
    "Mbps, 94% of frames through first time): the Mac was spending milliseconds of CPU on every frame. "
    "The whole driver is compiled unoptimised, and its AES is a byte-at-a-time textbook version. This "
    "build adds a table-driven AES compiled with optimisation, tests it against the old one on this Mac "
    "at startup (it is used only if it passes), times both, and logs where each frame's time goes. The "
    "bad-frame counter from k197 is off again. COLD boot.) "
    "(k198 was: FIXED RECEIVE ANTENNA 1, AN EXPERIMENT. k197 showed the receiver "
    "going mostly deaf for 77 s (the AP's beacons fell from ~10/s to 0-2/s) while everything the Mac sent "
    "still arrived: receive-only, and no corrupted frames at all. With auto-diversity 89% of frames came "
    "in on antenna 1. This build uses antenna 1 only (fixing the register the old fixed mode zeroed) and "
    "logs every frame's antenna per second. COLD boot.) "
    "(k197 was: RECEIVE-QUALITY INSTRUMENT. k196's capture showed the long download "
    "stalls are size-dependent: small file-sharing packets kept flowing while 1460-byte frames failed for "
    "minutes. The driver now also receives frames that failed their checksum (b43's monitor-mode switch) "
    "and counts them by rate, size and antenna, with signal strength and ACK-sent per frame; the receive "
    "timeline covers ~8.5 minutes. No behaviour change on the air. COLD boot.) "
    "(k196 was: RECEIVE ANTENNA BACK TO AUTO-DIVERSITY + STEADIER RATE CONTROL. A "
    "fixed-antenna experiment from k141 was never undone; its fixed-mode path also zeroed an antenna "
    "register. k195 then saw 70% of downlink frames at slow CCK rates and a 14 s receive outage, while "
    "Tiger on the same card moves 1.7-2 MB/s. Rate control no longer steps down for a single retry "
    "(retries here track airtime, not rate). Adds a 4-minute receive timeline to the snapshot. COLD boot.) "
    "(k195 was: A REAL TRANSMIT RING. Every frame used to go out of ONE buffer "
    "after a DMA-engine reset: the next frame overwrote the last before the card had read it (7.7% of "
    "sent packets lost in the k194 capture), and each reset discarded received frames still waiting. "
    "Now 32 frames can be in flight in b43's 256-descriptor ring, the receive side drains every frame "
    "per interrupt (was 4), and the every-32nd diagnostic broadcast is gone. COLD boot.) "
    "(k194 was: THE MISSING MIDDLE OF b43_wireless_core_init. k193's OFDM sped "
    "uploads up, but downloads went lossy (5% resent, a 67 s stall opening the share) the moment the AP "
    "began sending to us at OFDM. This port had skipped everything b43 does between chip_init and "
    "dma_init: the ucode's per-rate ACK/CTS entries (b43_rate_memory_init), the ACK/CTS PHY word, the "
    "fallback-rate limits, retry limits, contention window, and PHYTYPE/PHYVER. All now ported in b43's "
    "order and read back into the boot log. Keeps k193's OFDM + ARF. COLD boot.) "
    "(k193 was: 802.11g SPEED, STEP 1. Every data frame went out at 1 Mbps CCK "
    "and we advertised only 11b rates, so the AP treated this Mac as an 11b client (~40 KB/s uploads). "
    "Now: advertise 6-54 Mbps; data frames at OFDM with a minimal ARF (start 24 Mbps; 10 clean sends "
    "-> up to 36/48/54; 2 misses -> down, floor 1 Mbps CCK) and CCK 1 as the in-frame fallback; each "
    "frame's rate rides in its status cookie. Join frames unchanged. Snapshot: per-rate TX results, "
    "RX OFDM/CCK split. COLD boot.) (k192 was: LARGE FRAMES NOW RECEIVED. The receive pump copied only the first "
    "512 bytes of each frame (a buffer sized for the WPA2 join); anything over a ~438-byte Ethernet "
    "frame lost its tail and MIC and was dropped as a decrypt failure. DHCP (~350) worked; the Pi's "
    "467-byte AFP reply never arrived, so the Finder hung on a starving TCP connection. Buffer now 2400 "
    "+ a guard so the decrypt can never read past it; snapshot prints drop reasons and the largest frame "
    "delivered. Includes k191's putbq back-off, which real TCP throughput now needs. COLD boot.) "
    "(k191 was: THE FREEZE ON THE FIRST REAL TCP TRAFFIC. k190 got the first DHCP "
    "lease ever (192.168.1.225); the first AFP connect then froze the machine, as did the next boot at "
    "the desktop. The receive service routine requeued with putq when OT's upper layer was full; putq "
    "re-enables the queue, so the routine was rescheduled at once, found it still full, requeued... a "
    "STREAMS livelock. It never ran before k190 (every frame went to ARP, which never fills). Now putbq: "
    "back at the head, no self-reschedule -- the STREAMS back-off Apple's own OTModl$radio imports. Also "
    "caps each stream's backlog at 64 frames (drop + count) so a stalled upstream cannot drain OT's "
    "memory. Snapshot shows per-stream backlog + cap drops. Keeps k190's per-stream routing. "
    "⚠ COLD boot required.) (k190 was: PER-STREAM DLPI STATE. TCP/IP opens SEVERAL streams on the port at "
    "once (IP binds 0x0800, ARP binds 0x0806); k189 run 2's snapshot showed qopen 2 before the first "
    "qclose. Through k189 the driver kept ONE read queue/state/SAP: each open overwrote the read queue, "
    "each bind overwrote the SAP, every received frame went up the LAST-opened stream whatever its "
    "protocol (930 frames, final bind = ARP), any close cut receive off for both, and INFO_ACK told a new "
    "stream it was already bound. Now each stream owns a slot (q_ptr, with the queue layout pinned by "
    "_Static_asserts) and each received frame goes up the bound stream(s) whose SAP matches its type. "
    "Snapshot gains a per-stream table (SAP / state / RX up) and a no-stream drop count. Also: every "
    "driver log now goes to the System Folder via FindFolder -- k189 run 2 scattered three copies across "
    "System Folder, Control Panels and Extensions. Keeps k189's module_info alignment fix. "
    "⚠ COLD boot required.)"
};

resource 'vers' (2, locked) {
    0x01, 0x99, beta, 219, verUS,
    "1.0b219",
    "AirPort Extreme 1.0b219 (k219: shows as AirPort Extreme in TCP/IP; auto antenna; BCM4306 check)"
};
